    ('0946a67c-9613-4042-8c80-4e6642fd40d1', '2023-04-10', E'Juntada de pe\u00e7as digitalizadas; intima\u00e7\u00e3o da SC', 'historico_separado', true),
    ('0946a67c-9613-4042-8c80-4e6642fd40d1', '2023-03-25', E'Intima\u00e7\u00e3o confirmada SC', 'historico_separado', true),
    ('0946a67c-9613-4042-8c80-4e6642fd40d1', '2023-03-15', E'Despacho: "A parte exequente anexou certid\u00e3o que comprova a exist\u00eancia de ve\u00edculo em nome do executado, remaescendo a certid\u00e3o atual do ve\u00edculo.Assim, efetue-se consulta no sistema RENAJUD. Na sequ\u00eancia, com a resposta, intime-se a parte exequente para manifesta\u00e7\u00e3o."', 'historico_separado', true),
